export function isLanguage(value: string | null | undefined): value is Language {
  return LANGUAGES.some((language) => language.code === value);
}

export function localizeText(source: string, language: Language): string {
  if (language === 'en' || !source.trim()) return source;

  const leading = source.match(/^\s*/)?.[0] ?? '';
  const trailing = source.match(/\s*$/)?.[0] ?? '';
  const text = source.trim();
  const exact = translations.get(text)?.[language]?.trim();
  if (exact) return `${leading}${exact}${trailing}`;

  const windScalePrefix = 'Wind totals 2 through 12. Green means safe; coral means a topple. ';
  if (text.startsWith(windScalePrefix)) {
    const detail = text.slice(windScalePrefix.length);
    const copy = windScaleCopy[language];
    let translatedDetail = detail.replace(
      /^Wind strengths (\d+) through 12 can topple this tower\./,
      (_match, first: string) => copy.strengths(first),
    );
    translatedDetail = translatedDetail.replace(/^All shown wind strengths are safe\./, copy.safe);
    translatedDetail = translatedDetail.replace(
      / Current wind (\d+) topples it\./,
      (_match, strength: string) => copy.currentTopples(strength),
    );
    translatedDetail = translatedDetail.replace(
      / Current wind (\d+) is safe\./,
      (_match, strength: string) => copy.currentSafe(strength),
    );
    return `${leading}${copy.label} ${translatedDetail}${trailing}`;
  }

  for (const [pattern, replacement] of [...dynamicPatterns[language], ...additionalPatterns[language]]) {
    if (pattern.test(text)) {
      return `${leading}${text.replace(pattern, replacement)}${trailing}`;
    }
  }

  return source;
}

export function localizeApp(root: HTMLElement, language: Language): void {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode();
  while (node) {
    node.textContent = localizeText(node.textContent ?? '', language);
    node = walker.nextNode();
  }

  for (const element of root.querySelectorAll<HTMLElement>('[aria-label], [placeholder], [title]')) {
    for (const attribute of ['aria-label', 'placeholder', 'title']) {
      const value = element.getAttribute(attribute);
      if (value !== null) element.setAttribute(attribute, localizeText(value, language));
    }
  }
}
